/**
 * @distilled.cloud/microsoft-graph -- Microsoft Graph SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the per-group
 * Smithy models `scripts/convert.ts` converts from Microsoft's v1.0 OpenAPI
 * description: one module per top-level tag group (`applications`,
 * `servicePrincipals`, `groups`, `users`, ...). Everything else in this
 * folder is hand-written.
 *
 * @example
 * ```ts
 * import * as MicrosoftGraph from "@distilled.cloud/microsoft-graph";
 *
 * const app = yield* MicrosoftGraph.applications.createApplication({
 *   displayName: "my-app",
 * });
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export {
  MicrosoftGraphProtocol,
  type MicrosoftGraphOpError,
  type MicrosoftGraphOpContext,
} from "./protocol.ts";
export * as Retry from "./retry.ts";
export * from "./services/index.ts";
